def query_error_logs(severity, start_time, end_time):
    credential = DefaultAzureCredential()
    client = LogsQueryClient(credential)
    query = f"exceptions | where severity == '{severity}' and timestamp >= datetime({start_time}) and timestamp <= datetime({end_time})"
    response = client.query_workspace('<YOUR_WORKSPACE_ID>', query)
    if response.status == LogsQueryStatus.SUCCESS:
        for row in response.tables[0].rows:
            print(row)
    else:
        print('Query failed')

if __name__ == '__main__':
